-- interview-flyback-fix 拆檔（2026-08-15）
-- 原檔 109 KB、單行最長 20 KB，Supabase SQL Editor 貼進去會被截斷，
-- 報 ERROR 42601: syntax error at end of input（語句沒收尾）。
-- 一題一檔，內容與原檔逐字相同。冪等，重跑安全（這是 update 不是 insert）。

-- interview-flyback-fix.sql — q28–q32 共用底圖：改用站上的符號庫重畫
-- 為什麼要跑：這五筆 DB 已含舊圖，前端回填只補「沒有圖」的答案，不會覆蓋既有圖。
-- 改了什麼：整張重畫。元件改用 schematic-symbols.js（電阻鋸齒、MOSFET 有體二極體、
--           繞組是線圈不是方框），白底藍線條，字級 11，四語共用同一張。
-- 驗證：interview-diagram-check 0 發現；verify-batch12.js 66 條拓樸/極性斷言全過；
--       瀏覽器 getBBox+getCTM 實測重疊 0。
-- 用法：Supabase Dashboard → SQL Editor → 全部貼上 → Run。冪等，可重跑。

-- q30：共模雜訊路徑 + CY
update public.interview_questions set
  answer = case when answer like '%<svg%'
    then regexp_replace(answer, $re$<div class="exam-diagram-box">.*</svg></div>$re$, n.box)
    when answer like '%<div class="exam-diagram-box"></div>%'
    then replace(answer, $re$<div class="exam-diagram-box"></div>$re$, n.box)
    when answer is not null then n.box || answer
    else answer end,
  answer_en = case when answer_en like '%<svg%'
    then regexp_replace(answer_en, $re$<div class="exam-diagram-box">.*</svg></div>$re$, n.box)
    when answer_en like '%<div class="exam-diagram-box"></div>%'
    then replace(answer_en, $re$<div class="exam-diagram-box"></div>$re$, n.box)
    when answer_en is not null then n.box || answer_en
    else answer_en end,
  answer_ja = case when answer_ja like '%<svg%'
    then regexp_replace(answer_ja, $re$<div class="exam-diagram-box">.*</svg></div>$re$, n.box)
    when answer_ja like '%<div class="exam-diagram-box"></div>%'
    then replace(answer_ja, $re$<div class="exam-diagram-box"></div>$re$, n.box)
    when answer_ja is not null then n.box || answer_ja
    else answer_ja end,
  answer_ko = case when answer_ko like '%<svg%'
    then regexp_replace(answer_ko, $re$<div class="exam-diagram-box">.*</svg></div>$re$, n.box)
    when answer_ko like '%<div class="exam-diagram-box"></div>%'
    then replace(answer_ko, $re$<div class="exam-diagram-box"></div>$re$, n.box)
    when answer_ko is not null then n.box || answer_ko
    else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="720" height="480" viewBox="0 0 720 480" xmlns="http://www.w3.org/2000/svg"><rect width="720" height="480" fill="#ffffff"/><text x="360" y="20" fill="#1d2943" font-size="13" text-anchor="middle" font-weight="bold">Flyback charger: where common-mode noise goes</text><path d="M 450 244 V 178 H 472 V 130 H 508 V 300 H 516 V 380 H 472 V 352" fill="none" stroke="#16a34a" stroke-width="9" stroke-opacity="0.30" stroke-linecap="round" stroke-linejoin="round"/><text x="12" y="84" fill="#1d2943" font-size="11" text-anchor="end" font-weight="bold">L</text><text x="12" y="124" fill="#1d2943" font-size="11" text-anchor="end" font-weight="bold">N</text><line x1="16" y1="80" x2="100" y2="80" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="fuse"><rect x="52" y="73" width="30" height="14" fill="none" stroke="#1f4fd1" stroke-width="2"/></g><text x="67" y="64" fill="#1d2943" font-size="11" text-anchor="middle" font-weight="bold">F1</text><line x1="16" y1="120" x2="100" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><g data-sym="inductor"><line x1="100" y1="80" x2="106" y2="80" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><path d="M 106 80 A 4.5 4.5 0 1 1 115 80 A 4.5 4.5 0 1 1 124 80 A 4.5 4.5 0 1 1 133 80 A 4.5 4.5 0 1 1 142 80" fill="none" stroke="#1f4fd1" stroke-width="2"/><line x1="142" y1="80" x2="148" y2="80" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><g data-sym="inductor"><line x1="100" y1="120" x2="106" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/><path d="M 106 120 A 4.5 4.5 0 1 1 115 120 A 4.5 4.5 0 1 1 124 120 A 4.5 4.5 0 1 1 133 120 A 4.5 4.5 0 1 1 142 120" fill="none" stroke="#1f4fd1" stroke-width="2"/><line x1="142" y1="120" x2="148" y2="120" stroke="#1f4fd1" stroke-width="2" stroke-linecap="round"/></g><line x1="100" y1="96" x2="148" y2="96" stroke="#1f4fd1" stroke-width="1.6" stroke-linecap="round"/><line x1="100